import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.DQQHyi2x.js";const p=JSON.parse('{"title":"Agent Mail","description":"","frontmatter":{},"headers":[],"relativePath":"features/agent-mail.md","filePath":"features/agent-mail.md"}'),n={name:"features/agent-mail.md"};function i(l,e,r,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="agent-mail" tabindex="-1">Agent Mail <a class="header-anchor" href="#agent-mail" aria-label="Permalink to &quot;Agent Mail&quot;">​</a></h1><p>Agent Mail lets local Claude Code and Codex CLI sessions coordinate as a user-directed team. Claude Deck keeps durable mail participants, groups them by repository, tracks ephemeral sessions under those participants, and gives agents structured mailboxes for context requests, handoffs, broadcasts, and replies.</p><h2 id="what-it-is-for" tabindex="-1">What It Is For <a class="header-anchor" href="#what-it-is-for" aria-label="Permalink to &quot;What It Is For&quot;">​</a></h2><ul><li>Ask the agent that knows one repository to explain a local API, component, convention, or failure mode to another agent.</li><li>Hand work from one repository agent to another with touched files and next steps.</li><li>Keep short-lived agent sessions attached to a durable repo or Agent Team slot participant, so role and charter survive restarts and context compaction.</li><li>Inspect team communication from Claude Deck without turning the product into a general chat app.</li></ul><h2 id="how-agents-connect" tabindex="-1">How Agents Connect <a class="header-anchor" href="#how-agents-connect" aria-label="Permalink to &quot;How Agents Connect&quot;">​</a></h2><p>Claude Code gets both MCP tools and command hooks:</p><ul><li>The MCP server exposes <code>deck_whoami</code>, <code>deck_list_team</code>, <code>deck_check_inbox</code>, <code>deck_send_message</code>, <code>deck_reply</code>, <code>deck_ack_message</code>, <code>deck_request_context</code>, and <code>deck_create_handoff</code>.</li><li>Session and prompt hooks inject state-based mailbox context into the agent conversation.</li><li>Hook failures are soft, so a Deck outage should not break an agent session.</li></ul><p>Codex CLI gets the MCP server through <code>codex mcp add</code> and lifecycle hooks for session registration, activity updates, and inbox reminders. Codex agents should still check their inbox through the MCP tools when starting and finishing work because hook delivery is a reminder path, not a replacement for agent action.</p><h2 id="delivery-nudges" tabindex="-1">Delivery Nudges <a class="header-anchor" href="#delivery-nudges" aria-label="Permalink to &quot;Delivery Nudges&quot;">​</a></h2><p>When a message is delivered to a reachable Claude Code or Codex member, Claude Deck tries to wake it with an inbox-check prompt. The automatic nudge is best-effort and throttled per recipient, so rapid message bursts do not keep injecting prompts into the same session. The <strong>Queue inbox check</strong> button remains available for a manual retry when the UI shows unread or pending mail.</p><p>Claude Deck uses one visible wake path:</p><ul><li>tmux-observed sessions can be nudged through Agent Bridge by sending text and <code>Enter</code> to the pane.</li></ul><p>Non-tmux Claude Code and Codex sessions can still receive and send Agent Mail through MCP, but Claude Deck cannot wake their visible terminal session yet. Messages for those sessions remain delivered and unread until the agent calls <code>deck_check_inbox</code> or reaches a provider hook boundary. Agents should call <code>deck_check_inbox</code> before major work and after finishing a task.</p><h2 id="external-local-callers" tabindex="-1">External Local Callers <a class="header-anchor" href="#external-local-callers" aria-label="Permalink to &quot;External Local Callers&quot;">​</a></h2><p>Local tools such as OpenClaw can use the external Agent Mail API to authenticate as a named local actor, discover participants, send direct messages, request context, create handoffs, and poll request status.</p><p>See <a href="./external-agent-orchestration.html">External Agent Orchestration</a> for token setup, endpoint examples, delivery result semantics, and Agent Teams launch integration.</p><h2 id="setup-checklist" tabindex="-1">Setup Checklist <a class="header-anchor" href="#setup-checklist" aria-label="Permalink to &quot;Setup Checklist&quot;">​</a></h2><ol><li>Open <strong>Agent Mail</strong> in Claude Deck.</li><li>Use the <strong>Install</strong> tab to install the integration for Claude Code, Codex CLI, or both.</li><li>Restart or resume the affected agent sessions so their MCP configuration is loaded.</li><li>Have each agent call <code>deck_whoami</code> once from its repository.</li><li>Ask agents to call <code>deck_check_inbox</code> before starting major work and after finishing a task.</li></ol><p>Without this setup, the page can still show install status, but agents cannot exchange Agent Mail messages.</p><h2 id="current-limits" tabindex="-1">Current Limits <a class="header-anchor" href="#current-limits" aria-label="Permalink to &quot;Current Limits&quot;">​</a></h2><ul><li>Visibility is machine-global. Every local participant is visible to every other participant.</li><li>Sessions without Agent Team slot context use one repo-level participant. Agent Team slots can create multiple distinct participants in the same repo, such as planner/reviewer and implementer.</li><li>External Agent Mail calls use local actor bearer tokens. Token creation is loopback-only and follows Claude Deck&#39;s local trust model.</li><li>External callers should only use the API from the same trusted machine until a broader Claude Deck auth model exists.</li><li>Agent Mail is coordination state, not source control. Handoffs should still reference files, branches, issues, or commits when durable provenance matters.</li></ul><h2 id="install-details" tabindex="-1">Install Details <a class="header-anchor" href="#install-details" aria-label="Permalink to &quot;Install Details&quot;">​</a></h2><p>Open <strong>Agent Mail</strong> in Claude Deck and use the <strong>Install</strong> tab.</p><ul><li>Claude Code install adds user-scope command hooks and a user-scope MCP server.</li><li>Codex install runs the Codex CLI MCP installer and writes Agent Mail lifecycle hooks.</li><li>Install and uninstall actions require confirmation and attempt a backup before mutating config.</li></ul><p>The Install tab also shows manual Codex snippets for config and <code>AGENTS.md</code>.</p>',25)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
